    { const char * tb_v875 = "TB_API double exp(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v875; }
    { const char * tb_v876 = "    if (x > 709) return 1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v876; }
