    { const char * tb_v1452 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1452; }
    { const char * tb_v1453 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1453; }
