    { const char * tb_v1484 = "        \"  movl %cr0, %eax\\n  andl $0xFFFFFFFB, %eax\\n  orl $0x80010002, %eax\\n  movl %eax, %cr0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1484; }
    { const char * tb_v1485 = "        \"  ljmpl $0x18, $(0x8000 + (tb_tr64 - tb_tramp))\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1485; }
