    { const char * tb_v1664 = "// «узких» функций (fopen, mkdir, getenv...) берёт кодовую страницу ANSI, и русские\n"; *(const char * *)tb_grow(v_lines) = tb_v1664; }
    { const char * tb_v1665 = "// имена ломаются. Поэтому здесь свои обёртки через «широкие» функции (_wfopen...),\n"; *(const char * *)tb_grow(v_lines) = tb_v1665; }
    { const char * tb_v1666 = "// а имена POSIX ниже подменяются на них — код библиотеки остаётся одним на все системы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1666; }
    { const char * tb_v1667 = "#ifndef WIN32_LEAN_AND_MEAN\n"; *(const char * *)tb_grow(v_lines) = tb_v1667; }
