    { const char * tb_v1691 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v1691; }
    { const char * tb_v1692 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1692; }
    { const char * tb_v1693 = "TB_API FILE *tb_win_fopen(const char *path, const char *mode) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1693; }
    { const char * tb_v1694 = "    wchar_t *p = tb_wide(path), *m = tb_wide(mode);\n"; *(const char * *)tb_grow(v_lines) = tb_v1694; }
    { const char * tb_v1695 = "    FILE *f = p && m ? _wfopen(p, m) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1695; }
