    { const char * tb_v1699 = "TB_API int tb_win_stat(const char *path, struct stat *st) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1699; }
    { const char * tb_v1700 = "    wchar_t *p = tb_wide(path);\n"; *(const char * *)tb_grow(v_lines) = tb_v1700; }
    { const char * tb_v1701 = "    if (!p) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1701; }
    { const char * tb_v1702 = "    // «папка/» с косой чертой в конце _wstat не находит\n"; *(const char * *)tb_grow(v_lines) = tb_v1702; }
    { const char * tb_v1703 = "    size_t n = wcslen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v1703; }
    { const char * tb_v1704 = "    while (n > 1 && (p[n - 1] == L'/' || p[n - 1] == L'\\\\') && p[n - 2] != L':') p[--n] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1704; }
    { const char * tb_v1705 = "    struct _stat64 s;\n"; *(const char * *)tb_grow(v_lines) = tb_v1705; }
