    { const char * tb_v1728 = "// getenv в UTF-8; ответ живёт до конца программы (их мало и они короткие).\n"; *(const char * *)tb_grow(v_lines) = tb_v1728; }
    { const char * tb_v1729 = "// HOME на Windows обычно нет: тогда это USERPROFILE (C:\\Users\\имя)\n"; *(const char * *)tb_grow(v_lines) = tb_v1729; }
    { const char * tb_v1730 = "TB_API char *tb_win_getenv(const char *name) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1730; }
    { const char * tb_v1731 = "    wchar_t *n = tb_wide(name);\n"; *(const char * *)tb_grow(v_lines) = tb_v1731; }
    { const char * tb_v1732 = "    const wchar_t *v = n ? _wgetenv(n) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1732; }
    { const char * tb_v1733 = "    if (!v && strcmp(name, \"HOME\") == 0) v = _wgetenv(L\"USERPROFILE\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1733; }
    { const char * tb_v1734 = "    free(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1734; }
