    { const char * tb_v1737 = "// cmd.exe /c убирает первую и последнюю кавычку, если кавычек больше двух:\n"; *(const char * *)tb_grow(v_lines) = tb_v1737; }
    { const char * tb_v1738 = "// поэтому команда целиком берётся ещё в одни кавычки\n"; *(const char * *)tb_grow(v_lines) = tb_v1738; }
    { const char * tb_v1739 = "TB_API wchar_t *tb_win_cmd(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1739; }
    { const char * tb_v1740 = "    size_t n = strlen(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v1740; }
    { const char * tb_v1741 = "    char *q = malloc(n + 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v1741; }
    { const char * tb_v1742 = "    if (!q) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1742; }
