    { const char * tb_v1761 = "struct tb_win_dirent { char d_name[MAX_PATH * 4]; };\n"; *(const char * *)tb_grow(v_lines) = tb_v1761; }
    { const char * tb_v1762 = "typedef struct { _WDIR *d; struct tb_win_dirent e; } tb_win_dir;\n"; *(const char * *)tb_grow(v_lines) = tb_v1762; }
    { const char * tb_v1763 = "TB_API tb_win_dir *tb_win_opendir(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1763; }
