    { const char * tb_v2176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2176; }
    { const char * tb_v2177 = "// память у системы: mmap всегда отдаёт нули и выровнено по 64 КБ (лишнее по краям отдаём назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v2177; }
    { const char * tb_v2178 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2178; }
    { const char * tb_v2179 = "// Windows: VirtualAlloc тоже даёт нули, и адрес у него всегда кратен 64 КБ — обрезать нечего.\n"; *(const char * *)tb_grow(v_lines) = tb_v2179; }
    { const char * tb_v2180 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v2180; }
    { const char * tb_v2181 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2181; }
    { const char * tb_v2182 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2182; }
    { const char * tb_v2183 = "    if (!m) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2183; }
    { const char * tb_v2184 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v2184; }
    { const char * tb_v2185 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2185; }
    { const char * tb_v2186 = "#define munmap(p, n) (VirtualFree((p), 0, MEM_RELEASE) ? 0 : -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2186; }
    { const char * tb_v2187 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2187; }
    { const char * tb_v2188 = "#include <sys/mman.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2188; }
    { const char * tb_v2189 = "#ifdef __linux__\n"; *(const char * *)tb_grow(v_lines) = tb_v2189; }
    { const char * tb_v2190 = "#ifndef MREMAP_MAYMOVE\n"; *(const char * *)tb_grow(v_lines) = tb_v2190; }
    { const char * tb_v2191 = "#define MREMAP_MAYMOVE 1\n"; *(const char * *)tb_grow(v_lines) = tb_v2191; }
    { const char * tb_v2192 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2192; }
