    { const char * tb_v2195 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2195; }
    { const char * tb_v2196 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v2196; }
    { const char * tb_v2197 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2197; }
    { const char * tb_v2198 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2198; }
    { const char * tb_v2199 = "    size_t tot = (size_t)size + (size_t)TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v2199; }
    { const char * tb_v2200 = "    char *m = mmap(0, tot, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2200; }
    { const char * tb_v2201 = "    if (m == MAP_FAILED) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2201; }
    { const char * tb_v2202 = "    uintptr_t a = ((uintptr_t)m + TB_GPG - 1) & ~(uintptr_t)(TB_GPG - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2202; }
    { const char * tb_v2203 = "    if (a > (uintptr_t)m) munmap(m, a - (uintptr_t)m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2203; }
    { const char * tb_v2204 = "    size_t tail = (uintptr_t)m + tot - (a + (size_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2204; }
    { const char * tb_v2205 = "    if (tail) munmap((char *)a + size, tail);\n"; *(const char * *)tb_grow(v_lines) = tb_v2205; }
    { const char * tb_v2206 = "    return (char *)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v2206; }
    { const char * tb_v2207 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2207; }
    { const char * tb_v2208 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2208; }
    { const char * tb_v2209 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v2209; }
    { const char * tb_v2210 = "TB_API char *tb_gfresh = 0, *tb_gfresh_end = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2210; }
    { const char * tb_v2211 = "TB_API void *tb_gspare = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2211; }
    { const char * tb_v2212 = "TB_API char *tb_gpage_mem(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
    { const char * tb_v2213 = "    if (tb_gspare) { void *p = tb_gspare; tb_gspare = *(void **)p; *(void **)p = 0; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2213; }
    { const char * tb_v2214 = "    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2214; }
    { const char * tb_v2215 = "    char *p = tb_gfresh;\n"; *(const char * *)tb_grow(v_lines) = tb_v2215; }
    { const char * tb_v2216 = "    tb_gfresh += TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v2216; }
    { const char * tb_v2217 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
    { const char * tb_v2218 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2218; }
    { const char * tb_v2219 = "TB_API tb_gpage *tb_gnewpage(int cls, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2219; }
    { const char * tb_v2220 = "    tb_gpage *pg = calloc(1, sizeof(tb_gpage));\n"; *(const char * *)tb_grow(v_lines) = tb_v2220; }
    { const char * tb_v2221 = "    if (!pg) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2221; }
    { const char * tb_v2222 = "    pg->start = tb_gpage_mem();\n"; *(const char * *)tb_grow(v_lines) = tb_v2222; }
