    { const char * tb_v2224 = "    pg->inv = ((1ULL << 32) + pg->bsize - 1) / pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "    pg->fl = calloc(pg->nblocks, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
    { const char * tb_v2226 = "    if (!pg->fl) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2226; }
    { const char * tb_v2227 = "    pg->free = 0; pg->bump = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2227; }
    { const char * tb_v2228 = "    pg->nfree = pg->nblocks;\n"; *(const char * *)tb_grow(v_lines) = tb_v2228; }
    { const char * tb_v2229 = "    pg->next = tb_gall; tb_gall = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2229; }
    { const char * tb_v2230 = "    tb_gmap_add(pg, TB_GPG);\n"; *(const char * *)tb_grow(v_lines) = tb_v2230; }
    { const char * tb_v2231 = "    pg->anext = tb_gavail[np][cls]; tb_gavail[np][cls] = pg; pg->in_avail = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
    { const char * tb_v2233 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2233; }
    { const char * tb_v2234 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v2234; }
    { const char * tb_v2235 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v2235; }
    { const char * tb_v2236 = "TB_INL char *tb_gblock(uintptr_t a, tb_gpage **out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2236; }
    { const char * tb_v2237 = "    if (a < tb_glo || a >= tb_ghi) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2237; }
    { const char * tb_v2238 = "    tb_gpage *pg = tb_gmap_get(a);\n"; *(const char * *)tb_grow(v_lines) = tb_v2238; }
    { const char * tb_v2239 = "    if (!pg) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2239; }
    { const char * tb_v2240 = "    if (pg->large) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2240; }
    { const char * tb_v2241 = "        if (a >= (uintptr_t)pg->start + (uintptr_t)pg->nbytes) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2241; }
    { const char * tb_v2242 = "        *out = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2242; }
    { const char * tb_v2243 = "        return pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v2243; }
    { const char * tb_v2244 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "    long long i = TB_GIDX(pg, a - (uintptr_t)pg->start);\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
    { const char * tb_v2246 = "    if (i >= pg->nblocks || !(pg->fl[i] & 1)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2246; }
    { const char * tb_v2247 = "    *out = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2247; }
    { const char * tb_v2248 = "    return pg->start + i * pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v2248; }
    { const char * tb_v2249 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2249; }
    { const char * tb_v2250 = "TB_API void tb_gc_collect(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2250; }
    { const char * tb_v2251 = "TB_API void *tb_galloc_locked(long long n, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2251; }
