    { const char * tb_v2648 = "    if (TB_RARE((unsigned long long)i >= (unsigned long long)l->len)) tb_crash(line, \"номер за пределами списка\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2648; }
    { const char * tb_v2649 = "    return TB_BIT(l, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v2649; }
