    { const char * tb_v2685 = "    unsigned long long *w = (unsigned long long *)l->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v2685; }
    { const char * tb_v2686 = "    long long i = l->len;\n"; *(const char * *)tb_grow(v_lines) = tb_v2686; }
