    { const char * tb_v2753 = "// ---------- буквы: len, s[i], cut, find, code, char и each считают буквы, а не байты ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2753; }
    { const char * tb_v2754 = "// Текст хранится в UTF-8: латинская буква — 1 байт, русская — 2, иероглиф — 3, смайлик — 4.\n"; *(const char * *)tb_grow(v_lines) = tb_v2754; }
    { const char * tb_v2755 = "// Байт, который не складывается в букву (испорченный UTF-8, байты с диска), — сам себе буква.\n"; *(const char * *)tb_grow(v_lines) = tb_v2755; }
    { const char * tb_v2756 = "TB_INL long long tb_u8n(const unsigned char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2756; }
    { const char * tb_v2757 = "    unsigned char b = p[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v2757; }
    { const char * tb_v2758 = "    if (b < 0xC2 || b > 0xF4) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2758; }
    { const char * tb_v2759 = "    long long need = b < 0xE0 ? 2 : b < 0xF0 ? 3 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "    for (long long k = 1; k < need; k++) if ((p[k] & 0xC0) != 0x80) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "    return need;\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "// сколько букв в первых nb байтах\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
    { const char * tb_v2764 = "TB_API long long tb_u8count(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "    const unsigned char *p = (const unsigned char *)s, *e = p + nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
    { const char * tb_v2766 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2766; }
    { const char * tb_v2767 = "    while (p < e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2767; }
    { const char * tb_v2768 = "        if (*p < 0x80) { p++; n++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2768; }
    { const char * tb_v2769 = "        long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2769; }
    { const char * tb_v2770 = "        if (p + k > e) k = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2770; }
    { const char * tb_v2771 = "        p += k; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2771; }
    { const char * tb_v2772 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2772; }
    { const char * tb_v2773 = "    return n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2773; }
    { const char * tb_v2774 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2774; }
    { const char * tb_v2775 = "// память о последних текстах: адрес, байты, буквы и где мы стояли (буква li начинается с байта bi).\n"; *(const char * *)tb_grow(v_lines) = tb_v2775; }
    { const char * tb_v2776 = "// s[i] подряд в цикле — шаг вперёд от прошлого места, а не счёт с начала.\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "typedef struct { const char *p; long long nb, nl, li, bi; } tb_u8slot;\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "TB_API _Thread_local tb_u8slot tb_u8c[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "TB_API _Thread_local int tb_u8c_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "TB_INL void tb_u8c_clear(void) { for (int k = 0; k < 4; k++) tb_u8c[k].p = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "// nb < 0: длину в байтах посчитать (текст не меняется); nb >= 0: текст, в который дописывают\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
    { const char * tb_v2782 = "TB_API tb_u8slot *tb_u8info(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2782; }
    { const char * tb_v2783 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2783; }
    { const char * tb_v2784 = "        tb_u8slot *c = &tb_u8c[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v2784; }
    { const char * tb_v2785 = "        if (c->p != s) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2785; }
    { const char * tb_v2786 = "        if (nb < 0 || nb == c->nb) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2786; }
    { const char * tb_v2787 = "        if (nb > c->nb) {   // дописали в конец: досчитать только новое\n"; *(const char * *)tb_grow(v_lines) = tb_v2787; }
    { const char * tb_v2788 = "            long long from = c->nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2788; }
    { const char * tb_v2789 = "            // последняя буква могла быть недописанной: пересчитать с её начала\n"; *(const char * *)tb_grow(v_lines) = tb_v2789; }
    { const char * tb_v2790 = "            while (from > 0 && ((unsigned char)s[from - 1] & 0xC0) == 0x80 && c->nb - from < 3) from--;\n"; *(const char * *)tb_grow(v_lines) = tb_v2790; }
    { const char * tb_v2791 = "            if (from > 0 && (unsigned char)s[from - 1] >= 0xC0) from--;\n"; *(const char * *)tb_grow(v_lines) = tb_v2791; }
    { const char * tb_v2792 = "            long long before = tb_u8count(s, from);\n"; *(const char * *)tb_grow(v_lines) = tb_v2792; }
    { const char * tb_v2793 = "            c->nl = before + tb_u8count(s + from, nb - from);\n"; *(const char * *)tb_grow(v_lines) = tb_v2793; }
    { const char * tb_v2794 = "            c->nb = nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2794; }
    { const char * tb_v2795 = "            if (c->bi > from) { c->li = 0; c->bi = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2795; }
    { const char * tb_v2796 = "            return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2796; }
    { const char * tb_v2797 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2797; }
    { const char * tb_v2798 = "        break;\n"; *(const char * *)tb_grow(v_lines) = tb_v2798; }
    { const char * tb_v2799 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2799; }
    { const char * tb_v2800 = "    tb_u8slot *c = &tb_u8c[tb_u8c_next];\n"; *(const char * *)tb_grow(v_lines) = tb_v2800; }
    { const char * tb_v2801 = "    tb_u8c_next = (tb_u8c_next + 1) & 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v2801; }
    { const char * tb_v2802 = "    c->p = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2802; }
    { const char * tb_v2803 = "    c->nb = nb >= 0 ? nb : (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v2803; }
    { const char * tb_v2804 = "    c->nl = tb_u8count(s, c->nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v2804; }
    { const char * tb_v2805 = "    c->li = 0; c->bi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2805; }
    { const char * tb_v2806 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
    { const char * tb_v2807 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2807; }
    { const char * tb_v2808 = "TB_API long long tb_ulen(const char *s) { return tb_u8info(s, -1)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2808; }
    { const char * tb_v2809 = "TB_API long long tb_ulen_n(const char *s, long long nb) { return nb < 0 ? tb_ulen(s) : tb_u8info(s, nb)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2809; }
    { const char * tb_v2810 = "// байт, с которого начинается буква i (i == букв — конец текста)\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "TB_API long long tb_u8off(tb_u8slot *c, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
    { const char * tb_v2812 = "    if (c->nl == c->nb) return i;   // одна латиница: буква = байт\n"; *(const char * *)tb_grow(v_lines) = tb_v2812; }
    { const char * tb_v2813 = "    const unsigned char *s = (const unsigned char *)c->p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2813; }
    { const char * tb_v2814 = "    long long li = c->li, bi = c->bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v2814; }
    { const char * tb_v2815 = "    if (i < li && i < li - i) { li = 0; bi = 0; }   // ближе к началу, чем к прошлому месту\n"; *(const char * *)tb_grow(v_lines) = tb_v2815; }
    { const char * tb_v2816 = "    while (li < i) { long long k = tb_u8n(s + bi); if (bi + k > c->nb) k = 1; bi += k; li++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2816; }
    { const char * tb_v2817 = "    while (li > i) {   // назад: на начало предыдущей буквы\n"; *(const char * *)tb_grow(v_lines) = tb_v2817; }
    { const char * tb_v2818 = "        long long b = bi - 1, back = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2818; }
    { const char * tb_v2819 = "        while (b > 0 && (s[b] & 0xC0) == 0x80 && back < 3) { b--; back++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2819; }
    { const char * tb_v2820 = "        if (b + tb_u8n(s + b) != bi) b = bi - 1;   // не сложилось в букву — один байт\n"; *(const char * *)tb_grow(v_lines) = tb_v2820; }
    { const char * tb_v2821 = "        bi = b; li--;\n"; *(const char * *)tb_grow(v_lines) = tb_v2821; }
    { const char * tb_v2822 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "    c->li = li; c->bi = bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "    return bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "// буквы из двух байт (русские, греческие...): готовые строки, как tb_chars для латиницы\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "TB_API char tb_chars2[2048 * 4];\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
