    { const char * tb_v2874 = "// дописать число: цифры пишутся прямо в конец, без отдельного текста\n"; *(const char * *)tb_grow(v_lines) = tb_v2874; }
    { const char * tb_v2875 = "TB_INL void tb_app_i(const char **p, long long *rl, long long *rc, long long x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2875; }
    { const char * tb_v2876 = "    char d[24]; int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2876; }
