    { const char * tb_v2883 = "// ядро отдаёт свой кусок в общий текст: если общий ещё пустой — забирает память куска целиком, без копии\n"; *(const char * *)tb_grow(v_lines) = tb_v2883; }
    { const char * tb_v2884 = "TB_API void tb_app_take(const char **p, long long *rl, long long *rc, const char *b, long long brl, long long brc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2884; }
    { const char * tb_v2885 = "    if (*rl < 0 && (*p)[0] == 0 && brl >= 0) { *p = b; *rl = brl; *rc = brc; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2885; }
    { const char * tb_v2886 = "    tb_app_n(p, rl, rc, b, brl >= 0 ? brl : (long long)strlen(b));\n"; *(const char * *)tb_grow(v_lines) = tb_v2886; }
    { const char * tb_v2887 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "    char *s = (char *)*p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
