    { const char * tb_v2921 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2921; }
    { const char * tb_v2922 = "// байты текста (для дисков, сети, форматов файлов): byte_len, byte_at, byte_char\n"; *(const char * *)tb_grow(v_lines) = tb_v2922; }
    { const char * tb_v2923 = "TB_API long long tb_byte_len(const char *s) { return tb_tlen(s); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2923; }
    { const char * tb_v2924 = "TB_API long long tb_byte_at(const char *s, long long i, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2924; }
    { const char * tb_v2925 = "    if (i < 0 || i >= tb_tlen(s)) tb_crash(line, \"byte_at: номер за пределами текста\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2925; }
    { const char * tb_v2926 = "    return (unsigned char)s[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
    { const char * tb_v2927 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2927; }
    { const char * tb_v2928 = "TB_API const char *tb_byte_char(long long b, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2928; }
    { const char * tb_v2929 = "    if (b < 1 || b > 255) tb_crash(line, \"byte_char: байт должен быть от 1 до 255 (байт 0 кончает текст)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2929; }
    { const char * tb_v2930 = "    return tb_chr(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v2930; }
    { const char * tb_v2931 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2931; }
    { const char * tb_v2932 = "TB_API long long tb_code(const char *s, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2932; }
    { const char * tb_v2933 = "    if (s[0] == 0) tb_crash(line, \"code: текст пустой\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2933; }
    { const char * tb_v2934 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2934; }
    { const char * tb_v2935 = "    long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2935; }
    { const char * tb_v2936 = "    if (k == 1) return p[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v2936; }
    { const char * tb_v2937 = "    if (k == 2) return ((p[0] & 0x1F) << 6) | (p[1] & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v2937; }
    { const char * tb_v2938 = "    if (k == 3) return ((p[0] & 0x0F) << 12) | ((p[1] & 0x3F) << 6) | (p[2] & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v2938; }
    { const char * tb_v2939 = "    return ((p[0] & 0x07) << 18) | ((p[1] & 0x3F) << 12) | ((p[2] & 0x3F) << 6) | (p[3] & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v2939; }
    { const char * tb_v2940 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2940; }
    { const char * tb_v2941 = "// char(1087) → \"п\": буква по её номеру в Юникоде\n"; *(const char * *)tb_grow(v_lines) = tb_v2941; }
    { const char * tb_v2942 = "TB_API const char *tb_uchr(long long x, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2942; }
    { const char * tb_v2943 = "    if (x < 1 || x > 0x10FFFF || (x >= 0xD800 && x <= 0xDFFF)) tb_crash(line, \"char: такого номера буквы нет (от 1 до 1114111)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2943; }
