    { const char * tb_v2945 = "    char b[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v2945; }
    { const char * tb_v2946 = "    if (x < 0x800) { b[0] = (char)(0xC0 | (x >> 6)); b[1] = (char)(0x80 | (x & 0x3F)); return tb_u8text(b, 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2946; }
    { const char * tb_v2947 = "    if (x < 0x10000) { b[0] = (char)(0xE0 | (x >> 12)); b[1] = (char)(0x80 | ((x >> 6) & 0x3F)); b[2] = (char)(0x80 | (x & 0x3F)); return tb_u8text(b, 3); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2947; }
    { const char * tb_v2948 = "    b[0] = (char)(0xF0 | (x >> 18)); b[1] = (char)(0x80 | ((x >> 12) & 0x3F)); b[2] = (char)(0x80 | ((x >> 6) & 0x3F)); b[3] = (char)(0x80 | (x & 0x3F));\n"; *(const char * *)tb_grow(v_lines) = tb_v2948; }
    { const char * tb_v2949 = "    return tb_u8text(b, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v2949; }
    { const char * tb_v2950 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2950; }
    { const char * tb_v2951 = "// переполнение int — остановка с номером строки (внутри danger числа заворачиваются, как в железе)\n"; *(const char * *)tb_grow(v_lines) = tb_v2951; }
    { const char * tb_v2952 = "TB_COLD TB_API void tb_ovf(int line) { tb_crash(line, \"число не помещается в int: больше 9223372036854775807 или меньше -9223372036854775808\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2952; }
    { const char * tb_v2953 = "TB_INL long long tb_addo(long long a, long long b, int line) { long long r; if (__builtin_expect(__builtin_add_overflow(a, b, &r), 0)) tb_ovf(line); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2953; }
    { const char * tb_v2954 = "TB_INL long long tb_subo(long long a, long long b, int line) { long long r; if (__builtin_expect(__builtin_sub_overflow(a, b, &r), 0)) tb_ovf(line); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2954; }
    { const char * tb_v2955 = "TB_INL long long tb_mulo(long long a, long long b, int line) { long long r; if (__builtin_expect(__builtin_mul_overflow(a, b, &r), 0)) tb_ovf(line); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2955; }
    { const char * tb_v2956 = "TB_INL long long tb_nego(long long a, int line) { if (__builtin_expect(a == (-9223372036854775807LL - 1), 0)) tb_ovf(line); return -a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2956; }
    { const char * tb_v2957 = "TB_API long long tb_div(long long a, long long b, int line) { if (b == 0) tb_crash(line, \"деление на ноль\"); if (b == -1) return tb_nego(a, line); return a / b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2957; }
