    { const char * tb_v3198 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3198; }
    { const char * tb_v3199 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
    { const char * tb_v3201 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v3201; }
    { const char * tb_v3202 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3202; }
    { const char * tb_v3203 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3203; }
    { const char * tb_v3204 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v3204; }
    { const char * tb_v3205 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v3205; }
    { const char * tb_v3206 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v3206; }
    { const char * tb_v3207 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
    { const char * tb_v3210 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v3210; }
    { const char * tb_v3211 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3211; }
    { const char * tb_v3212 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3212; }
    { const char * tb_v3213 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3213; }
    { const char * tb_v3214 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3214; }
    { const char * tb_v3215 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3215; }
    { const char * tb_v3216 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3216; }
    { const char * tb_v3217 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3217; }
    { const char * tb_v3218 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3218; }
    { const char * tb_v3219 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3219; }
    { const char * tb_v3220 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3220; }
    { const char * tb_v3221 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3221; }
    { const char * tb_v3222 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3222; }
    { const char * tb_v3223 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
    { const char * tb_v3224 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
    { const char * tb_v3225 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3225; }
    { const char * tb_v3226 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3226; }
    { const char * tb_v3227 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3227; }
    { const char * tb_v3228 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v3228; }
    { const char * tb_v3229 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3229; }
    { const char * tb_v3230 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v3230; }
    { const char * tb_v3231 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v3231; }
    { const char * tb_v3232 = "    while ((got = fread(buf + len, 1, cap - len - 1, p)) > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3232; }
    { const char * tb_v3233 = "        len += got;\n"; *(const char * *)tb_grow(v_lines) = tb_v3233; }
    { const char * tb_v3234 = "        if (len + 1 == cap) { buf = tb_resize(buf, cap, cap * 2); cap *= 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3234; }
    { const char * tb_v3235 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3235; }
    { const char * tb_v3236 = "    buf[len] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3236; }
    { const char * tb_v3237 = "    if (pclose(p) != 0) { tb_err = tb_cat(\"не получилось скачать (нет сети, нет curl или сервер ответил ошибкой): \", url); return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3237; }
