    { const char * tb_v3242 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3242; }
    { const char * tb_v3243 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v3243; }
    { const char * tb_v3244 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3244; }
    { const char * tb_v3245 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3245; }
    { const char * tb_v3246 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v3246; }
    { const char * tb_v3247 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3247; }
    { const char * tb_v3248 = "        while (*p && *p != '\"') { if (*p == '\\\\' && p[1]) p++; p++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3248; }
    { const char * tb_v3249 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3249; }
    { const char * tb_v3250 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3250; }
    { const char * tb_v3251 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v3251; }
    { const char * tb_v3252 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3252; }
    { const char * tb_v3253 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3253; }
    { const char * tb_v3254 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3254; }
    { const char * tb_v3255 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3255; }
    { const char * tb_v3256 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3256; }
    { const char * tb_v3257 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3257; }
    { const char * tb_v3258 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3258; }
    { const char * tb_v3259 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3259; }
    { const char * tb_v3260 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3260; }
    { const char * tb_v3261 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3261; }
