    { const char * tb_v3526 = "        tb_rand_state = ((unsigned long long)hi << 32 | lo) ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3526; }
    { const char * tb_v3527 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3527; }
