    { const char * tb_v3564 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
