    { const char * tb_v3622 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
