    { const char * tb_v3630 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
