    { const char * tb_v3639 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
