    { const char * tb_v4140 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4140; }
    { const char * tb_v4141 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v4141; }
    { const char * tb_v4142 = "    q->size = (uint64_t)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4142; }
    { const char * tb_v4143 = "    return (long long)(uintptr_t)(q + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4143; }
    { const char * tb_v4144 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4144; }
    { const char * tb_v4145 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v4145; }
    { const char * tb_v4146 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4146; }
    { const char * tb_v4147 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4147; }
    { const char * tb_v4148 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4148; }
    { const char * tb_v4149 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4149; }
    { const char * tb_v4150 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4150; }
    { const char * tb_v4151 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4151; }
    { const char * tb_v4152 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
    { const char * tb_v4154 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4154; }
    { const char * tb_v4155 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v4155; }
    { const char * tb_v4156 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4156; }
    { const char * tb_v4157 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v4157; }
    { const char * tb_v4158 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4158; }
    { const char * tb_v4159 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4159; }
    { const char * tb_v4160 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4160; }
    { const char * tb_v4161 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4161; }
    { const char * tb_v4162 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4162; }
    { const char * tb_v4163 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4163; }
    { const char * tb_v4164 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4164; }
    { const char * tb_v4165 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4165; }
    { const char * tb_v4166 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4166; }
    { const char * tb_v4167 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4167; }
    { const char * tb_v4168 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4168; }
    { const char * tb_v4169 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v4169; }
    { const char * tb_v4170 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v4170; }
    { const char * tb_v4171 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4171; }
    { const char * tb_v4172 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4172; }
    { const char * tb_v4173 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v4173; }
    { const char * tb_v4174 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v4174; }
    { const char * tb_v4175 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v4175; }
    { const char * tb_v4176 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4176; }
    { const char * tb_v4177 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4177; }
    { const char * tb_v4178 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4178; }
    { const char * tb_v4179 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4179; }
    { const char * tb_v4180 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4180; }
    { const char * tb_v4181 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v4181; }
    { const char * tb_v4182 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4182; }
    { const char * tb_v4183 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v4183; }
    { const char * tb_v4184 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4184; }
    { const char * tb_v4185 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v4185; }
    { const char * tb_v4186 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4186; }
    { const char * tb_v4187 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4187; }
    { const char * tb_v4188 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v4188; }
    { const char * tb_v4189 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4189; }
    { const char * tb_v4190 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v4190; }
    { const char * tb_v4191 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v4191; }
    { const char * tb_v4192 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4192; }
    { const char * tb_v4193 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v4193; }
    { const char * tb_v4194 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v4194; }
    { const char * tb_v4195 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4195; }
    { const char * tb_v4196 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4196; }
    { const char * tb_v4197 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v4197; }
    { const char * tb_v4198 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4198; }
    { const char * tb_v4199 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v4199; }
    { const char * tb_v4200 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v4200; }
    { const char * tb_v4201 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v4201; }
    { const char * tb_v4202 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4202; }
    { const char * tb_v4203 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v4203; }
    { const char * tb_v4204 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4204; }
    { const char * tb_v4205 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v4205; }
    { const char * tb_v4206 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4206; }
    { const char * tb_v4207 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4207; }
    { const char * tb_v4208 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4208; }
    { const char * tb_v4209 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v4209; }
    { const char * tb_v4210 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v4210; }
    { const char * tb_v4211 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4211; }
    { const char * tb_v4212 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v4212; }
    { const char * tb_v4213 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v4213; }
    { const char * tb_v4214 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v4214; }
    { const char * tb_v4215 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4215; }
    { const char * tb_v4216 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v4216; }
    { const char * tb_v4217 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4217; }
    { const char * tb_v4218 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v4218; }
    { const char * tb_v4219 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4219; }
    { const char * tb_v4220 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v4220; }
    { const char * tb_v4221 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v4221; }
    { const char * tb_v4222 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4222; }
    { const char * tb_v4223 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4223; }
    { const char * tb_v4224 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v4224; }
    { const char * tb_v4225 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4225; }
    { const char * tb_v4226 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4226; }
    { const char * tb_v4227 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v4227; }
    { const char * tb_v4228 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4228; }
    { const char * tb_v4229 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4229; }
    { const char * tb_v4230 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v4230; }
    { const char * tb_v4231 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4231; }
    { const char * tb_v4232 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v4232; }
    { const char * tb_v4233 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4233; }
    { const char * tb_v4234 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v4234; }
    { const char * tb_v4235 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4235; }
    { const char * tb_v4236 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4236; }
    { const char * tb_v4237 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4237; }
    { const char * tb_v4238 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v4238; }
    { const char * tb_v4239 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4239; }
    { const char * tb_v4240 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4240; }
    { const char * tb_v4241 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v4241; }
    { const char * tb_v4242 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4242; }
    { const char * tb_v4243 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v4243; }
    { const char * tb_v4244 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4244; }
    { const char * tb_v4245 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4245; }
    { const char * tb_v4246 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4246; }
    { const char * tb_v4247 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v4247; }
    { const char * tb_v4248 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4248; }
    { const char * tb_v4249 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4249; }
    { const char * tb_v4250 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4250; }
    { const char * tb_v4251 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4251; }
    { const char * tb_v4252 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v4252; }
    { const char * tb_v4253 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4253; }
    { const char * tb_v4254 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4254; }
    { const char * tb_v4255 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4255; }
    { const char * tb_v4256 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v4256; }
    { const char * tb_v4257 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4257; }
    { const char * tb_v4258 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4258; }
    { const char * tb_v4259 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4259; }
    { const char * tb_v4260 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v4260; }
    { const char * tb_v4261 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v4261; }
    { const char * tb_v4262 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v4262; }
    { const char * tb_v4263 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4263; }
    { const char * tb_v4264 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4264; }
    { const char * tb_v4265 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4265; }
    { const char * tb_v4266 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v4266; }
    { const char * tb_v4267 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4267; }
    { const char * tb_v4268 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4268; }
    { const char * tb_v4269 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4269; }
    { const char * tb_v4270 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4270; }
    { const char * tb_v4271 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4271; }
    { const char * tb_v4272 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4272; }
    { const char * tb_v4273 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4273; }
    { const char * tb_v4274 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4274; }
    { const char * tb_v4275 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4275; }
    { const char * tb_v4276 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4276; }
    { const char * tb_v4277 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v4277; }
    { const char * tb_v4278 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v4278; }
    { const char * tb_v4279 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v4279; }
    { const char * tb_v4280 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4280; }
    { const char * tb_v4281 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4281; }
    { const char * tb_v4282 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4282; }
    { const char * tb_v4283 = "    if (nb == 4) return *(volatile uint32_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4283; }
