    { const char * tb_v4667 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4667; }
    { const char * tb_v4668 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4668; }
    { const char * tb_v4669 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v4669; }
    { const char * tb_v4670 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4670; }
    { const char * tb_v4671 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v4671; }
    { const char * tb_v4672 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4672; }
    { const char * tb_v4673 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4673; }
    { const char * tb_v4674 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4674; }
    { const char * tb_v4675 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4675; }
    { const char * tb_v4676 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v4676; }
    { const char * tb_v4677 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4677; }
    { const char * tb_v4678 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4678; }
    { const char * tb_v4679 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4679; }
    { const char * tb_v4680 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4680; }
    { const char * tb_v4681 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v4681; }
    { const char * tb_v4682 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v4682; }
    { const char * tb_v4683 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4683; }
    { const char * tb_v4684 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v4684; }
    { const char * tb_v4685 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v4685; }
    { const char * tb_v4686 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v4686; }
    { const char * tb_v4687 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v4687; }
    { const char * tb_v4688 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4688; }
    { const char * tb_v4689 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4689; }
    { const char * tb_v4690 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4690; }
    { const char * tb_v4691 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v4691; }
    { const char * tb_v4692 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4692; }
    { const char * tb_v4693 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4693; }
    { const char * tb_v4694 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4694; }
    { const char * tb_v4695 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4695; }
    { const char * tb_v4696 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4696; }
    { const char * tb_v4697 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4697; }
    { const char * tb_v4698 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4698; }
    { const char * tb_v4699 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4699; }
    { const char * tb_v4700 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4700; }
    { const char * tb_v4701 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4701; }
    { const char * tb_v4702 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4702; }
    { const char * tb_v4703 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v4703; }
    { const char * tb_v4704 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v4704; }
    { const char * tb_v4705 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4705; }
    { const char * tb_v4706 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4706; }
    { const char * tb_v4707 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4707; }
    { const char * tb_v4708 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4708; }
    { const char * tb_v4709 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v4709; }
    { const char * tb_v4710 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4710; }
    { const char * tb_v4711 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4711; }
    { const char * tb_v4712 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v4712; }
    { const char * tb_v4713 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v4713; }
    { const char * tb_v4714 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v4714; }
    { const char * tb_v4715 = "       TB_K_CMD = 1, TB_K_CTRL = 2, TB_K_ALT = 3, TB_K_DEL = 4, TB_K_HOME = 5, TB_K_END = 6, TB_K_PGUP = 7,\n"; *(const char * *)tb_grow(v_lines) = tb_v4715; }
    { const char * tb_v4716 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v4716; }
    { const char * tb_v4717 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4717; }
    { const char * tb_v4718 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v4718; }
    { const char * tb_v4719 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v4719; }
