    { const char * tb_v5870 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v5870; }
    { const char * tb_v5871 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5871; }
    { const char * tb_v5872 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v5872; }
    { const char * tb_v5873 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v5873; }
    { const char * tb_v5874 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5874; }
    { const char * tb_v5875 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5875; }
    { const char * tb_v5876 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v5876; }
    { const char * tb_v5877 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5877; }
    { const char * tb_v5878 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5878; }
    { const char * tb_v5879 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5879; }
    { const char * tb_v5880 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5880; }
    { const char * tb_v5881 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5881; }
    { const char * tb_v5882 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5882; }
    { const char * tb_v5883 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5883; }
    { const char * tb_v5884 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5884; }
    { const char * tb_v5885 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v5885; }
    { const char * tb_v5886 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v5886; }
    { const char * tb_v5887 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5887; }
    { const char * tb_v5888 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5888; }
    { const char * tb_v5889 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5889; }
    { const char * tb_v5890 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5890; }
    { const char * tb_v5891 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5891; }
    { const char * tb_v5892 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v5892; }
    { const char * tb_v5893 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5893; }
    { const char * tb_v5894 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v5894; }
    { const char * tb_v5895 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5895; }
    { const char * tb_v5896 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v5896; }
    { const char * tb_v5897 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5897; }
    { const char * tb_v5898 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5898; }
    { const char * tb_v5899 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5899; }
    { const char * tb_v5900 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5900; }
    { const char * tb_v5901 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5901; }
    { const char * tb_v5902 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5902; }
    { const char * tb_v5903 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5903; }
    { const char * tb_v5904 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5904; }
    { const char * tb_v5905 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5905; }
    { const char * tb_v5906 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5906; }
    { const char * tb_v5907 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5907; }
    { const char * tb_v5908 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5908; }
    { const char * tb_v5909 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5909; }
    { const char * tb_v5910 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5910; }
    { const char * tb_v5911 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5911; }
    { const char * tb_v5912 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5912; }
    { const char * tb_v5913 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5913; }
    { const char * tb_v5914 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5914; }
    { const char * tb_v5915 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5915; }
    { const char * tb_v5916 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5916; }
    { const char * tb_v5917 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5917; }
    { const char * tb_v5918 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5918; }
    { const char * tb_v5919 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5919; }
    { const char * tb_v5920 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5920; }
    { const char * tb_v5921 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v5921; }
    { const char * tb_v5922 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5922; }
    { const char * tb_v5923 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5923; }
    { const char * tb_v5924 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v5924; }
    { const char * tb_v5925 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5925; }
    { const char * tb_v5926 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5926; }
    { const char * tb_v5927 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v5927; }
    { const char * tb_v5928 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5928; }
    { const char * tb_v5929 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5929; }
    { const char * tb_v5930 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5930; }
    { const char * tb_v5931 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5931; }
    { const char * tb_v5932 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5932; }
    { const char * tb_v5933 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5933; }
    { const char * tb_v5934 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v5934; }
    { const char * tb_v5935 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5935; }
    { const char * tb_v5936 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5936; }
    { const char * tb_v5937 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5937; }
    { const char * tb_v5938 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5938; }
    { const char * tb_v5939 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5939; }
    { const char * tb_v5940 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v5940; }
    { const char * tb_v5941 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5941; }
    { const char * tb_v5942 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v5942; }
    { const char * tb_v5943 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5943; }
    { const char * tb_v5944 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5944; }
    { const char * tb_v5945 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5945; }
    { const char * tb_v5946 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5946; }
    { const char * tb_v5947 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5947; }
    { const char * tb_v5948 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v5948; }
    { const char * tb_v5949 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v5949; }
