    { const char * tb_v5953 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v5953; }
    { const char * tb_v5954 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5954; }
    { const char * tb_v5955 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5955; }
    { const char * tb_v5956 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v5956; }
    { const char * tb_v5957 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v5957; }
    { const char * tb_v5958 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5958; }
    { const char * tb_v5959 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v5959; }
    { const char * tb_v5960 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5960; }
    { const char * tb_v5961 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5961; }
    { const char * tb_v5962 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5962; }
    { const char * tb_v5963 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5963; }
    { const char * tb_v5964 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5964; }
    { const char * tb_v5965 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5965; }
    { const char * tb_v5966 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5966; }
    { const char * tb_v5967 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5967; }
    { const char * tb_v5968 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5968; }
    { const char * tb_v5969 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v5969; }
    { const char * tb_v5970 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v5970; }
    { const char * tb_v5971 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5971; }
