    { const char * tb_v7597 = "    if (tb_my >= tb_gh) tb_my = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7597; }
    { const char * tb_v7598 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7598; }
    { const char * tb_v7599 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7599; }
