    { const char * tb_v8521 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8521; }
    { const char * tb_v8522 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v8522; }
    { const char * tb_v8523 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v8523; }
