    { const char * tb_v8632 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v8632; }
    { const char * tb_v8633 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v8633; }
    { const char * tb_v8634 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v8634; }
    { const char * tb_v8635 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v8635; }
    { const char * tb_v8636 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v8636; }
    { const char * tb_v8637 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v8637; }
    { const char * tb_v8638 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8638; }
    { const char * tb_v8639 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8639; }
    { const char * tb_v8640 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
    { const char * tb_v8641 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8641; }
    { const char * tb_v8642 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8642; }
    { const char * tb_v8643 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v8643; }
    { const char * tb_v8644 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8644; }
    { const char * tb_v8645 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v8645; }
    { const char * tb_v8646 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8646; }
    { const char * tb_v8647 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v8647; }
    { const char * tb_v8648 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8648; }
    { const char * tb_v8649 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8649; }
    { const char * tb_v8650 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8650; }
    { const char * tb_v8651 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v8651; }
    { const char * tb_v8652 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v8652; }
    { const char * tb_v8653 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8653; }
    { const char * tb_v8654 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8654; }
    { const char * tb_v8655 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8655; }
    { const char * tb_v8656 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8656; }
    { const char * tb_v8657 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8657; }
    { const char * tb_v8658 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8658; }
    { const char * tb_v8659 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8659; }
    { const char * tb_v8660 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8660; }
    { const char * tb_v8661 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8661; }
    { const char * tb_v8662 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8662; }
    { const char * tb_v8663 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8663; }
    { const char * tb_v8664 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8664; }
    { const char * tb_v8665 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8665; }
    { const char * tb_v8666 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8666; }
    { const char * tb_v8667 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8667; }
    { const char * tb_v8668 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8668; }
    { const char * tb_v8669 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8669; }
    { const char * tb_v8670 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8670; }
    { const char * tb_v8671 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8671; }
