    { const char * tb_v8673 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8673; }
    { const char * tb_v8674 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8674; }
    { const char * tb_v8675 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v8675; }
    { const char * tb_v8676 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8676; }
    { const char * tb_v8677 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8677; }
    { const char * tb_v8678 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v8678; }
    { const char * tb_v8679 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8679; }
    { const char * tb_v8680 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8680; }
