    { const char * tb_v8682 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8682; }
    { const char * tb_v8683 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8683; }
