    { const char * tb_v8700 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8700; }
    { const char * tb_v8701 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8701; }
