    { const char * tb_v8704 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8704; }
    { const char * tb_v8705 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8705; }
    { const char * tb_v8706 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8706; }
    { const char * tb_v8707 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8707; }
    { const char * tb_v8708 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v8708; }
    { const char * tb_v8709 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8709; }
    { const char * tb_v8710 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v8710; }
    { const char * tb_v8711 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v8711; }
    { const char * tb_v8712 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8712; }
    { const char * tb_v8713 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8713; }
    { const char * tb_v8714 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8714; }
    { const char * tb_v8715 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8715; }
    { const char * tb_v8716 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8716; }
    { const char * tb_v8717 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8717; }
    { const char * tb_v8718 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8718; }
    { const char * tb_v8719 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8719; }
    { const char * tb_v8720 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v8720; }
