    { const char * tb_v8722 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v8722; }
    { const char * tb_v8723 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8723; }
    { const char * tb_v8724 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8724; }
    { const char * tb_v8725 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8725; }
    { const char * tb_v8726 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8726; }
    { const char * tb_v8727 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v8727; }
    { const char * tb_v8728 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8728; }
    { const char * tb_v8729 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8729; }
    { const char * tb_v8730 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8730; }
    { const char * tb_v8731 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8731; }
    { const char * tb_v8732 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8732; }
    { const char * tb_v8733 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8733; }
    { const char * tb_v8734 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8734; }
    { const char * tb_v8735 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8735; }
    { const char * tb_v8736 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8736; }
    { const char * tb_v8737 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8737; }
    { const char * tb_v8738 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v8738; }
    { const char * tb_v8739 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8739; }
    { const char * tb_v8740 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8740; }
    { const char * tb_v8741 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v8741; }
    { const char * tb_v8742 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v8742; }
    { const char * tb_v8743 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v8743; }
    { const char * tb_v8744 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8744; }
    { const char * tb_v8745 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8745; }
    { const char * tb_v8746 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8746; }
    { const char * tb_v8747 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8747; }
    { const char * tb_v8748 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v8748; }
    { const char * tb_v8749 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8749; }
    { const char * tb_v8750 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v8750; }
    { const char * tb_v8751 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v8751; }
    { const char * tb_v8752 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v8752; }
    { const char * tb_v8753 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v8753; }
    { const char * tb_v8754 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8754; }
    { const char * tb_v8755 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8755; }
    { const char * tb_v8756 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v8756; }
    { const char * tb_v8757 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v8757; }
    { const char * tb_v8758 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8758; }
    { const char * tb_v8759 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8759; }
    { const char * tb_v8760 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8760; }
    { const char * tb_v8761 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v8761; }
    { const char * tb_v8762 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8762; }
    { const char * tb_v8763 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8763; }
    { const char * tb_v8764 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8764; }
    { const char * tb_v8765 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8765; }
    { const char * tb_v8766 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v8766; }
    { const char * tb_v8767 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v8767; }
    { const char * tb_v8768 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v8768; }
    { const char * tb_v8769 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8769; }
    { const char * tb_v8770 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8770; }
    { const char * tb_v8771 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v8771; }
    { const char * tb_v8772 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8772; }
    { const char * tb_v8773 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8773; }
    { const char * tb_v8774 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8774; }
    { const char * tb_v8775 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8775; }
    { const char * tb_v8776 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8776; }
    { const char * tb_v8777 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8777; }
    { const char * tb_v8778 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8778; }
    { const char * tb_v8779 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v8779; }
    { const char * tb_v8780 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8780; }
    { const char * tb_v8781 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8781; }
    { const char * tb_v8782 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8782; }
    { const char * tb_v8783 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v8783; }
    { const char * tb_v8784 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v8784; }
    { const char * tb_v8785 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8785; }
    { const char * tb_v8786 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8786; }
    { const char * tb_v8787 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8787; }
    { const char * tb_v8788 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8788; }
    { const char * tb_v8789 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8789; }
    { const char * tb_v8790 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8790; }
    { const char * tb_v8791 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8791; }
    { const char * tb_v8792 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8792; }
    { const char * tb_v8793 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8793; }
    { const char * tb_v8794 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8794; }
    { const char * tb_v8795 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8795; }
    { const char * tb_v8796 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8796; }
    { const char * tb_v8797 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8797; }
    { const char * tb_v8798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8798; }
    { const char * tb_v8799 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v8799; }
    { const char * tb_v8800 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8800; }
    { const char * tb_v8801 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8801; }
    { const char * tb_v8802 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8802; }
    { const char * tb_v8803 = "    a = (uint32_t)(a * (cov > 1 ? 1 : cov) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8803; }
    { const char * tb_v8804 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8804; }
    { const char * tb_v8805 = "    uint32_t *p = &tb_px[y * tb_gw + x];\n"; *(const char * *)tb_grow(v_lines) = tb_v8805; }
    { const char * tb_v8806 = "    *p = a >= 255 ? (c & 0xFFFFFF) : tb_mix(*p, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8806; }
    { const char * tb_v8807 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8807; }
    { const char * tb_v8808 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v8808; }
    { const char * tb_v8809 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v8809; }
    { const char * tb_v8810 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8810; }
    { const char * tb_v8811 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8811; }
