    { const char * tb_v8818 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8818; }
    { const char * tb_v8819 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8819; }
    { const char * tb_v8820 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8820; }
    { const char * tb_v8821 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8821; }
    { const char * tb_v8822 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8822; }
    { const char * tb_v8823 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8823; }
    { const char * tb_v8824 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8824; }
