    { const char * tb_v8828 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8828; }
    { const char * tb_v8829 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8829; }
    { const char * tb_v8830 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8830; }
    { const char * tb_v8831 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8831; }
    { const char * tb_v8832 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8832; }
