    { const char * tb_v8839 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v8839; }
    { const char * tb_v8840 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8840; }
    { const char * tb_v8841 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v8841; }
    { const char * tb_v8842 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8842; }
    { const char * tb_v8843 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v8843; }
    { const char * tb_v8844 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8844; }
    { const char * tb_v8845 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8845; }
