    { const char * tb_v8850 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8850; }
    { const char * tb_v8851 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v8851; }
