    { const char * tb_v8878 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v8878; }
    { const char * tb_v8879 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8879; }
    { const char * tb_v8880 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8880; }
    { const char * tb_v8881 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v8881; }
    { const char * tb_v8882 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8882; }
