    { const char * tb_v8891 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8891; }
    { const char * tb_v8892 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8892; }
    { const char * tb_v8893 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8893; }
    { const char * tb_v8894 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v8894; }
    { const char * tb_v8895 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v8895; }
    { const char * tb_v8896 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8896; }
    { const char * tb_v8897 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v8897; }
    { const char * tb_v8898 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8898; }
    { const char * tb_v8899 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v8899; }
    { const char * tb_v8900 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8900; }
    { const char * tb_v8901 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8901; }
    { const char * tb_v8902 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8902; }
    { const char * tb_v8903 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8903; }
    { const char * tb_v8904 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8904; }
    { const char * tb_v8905 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v8905; }
    { const char * tb_v8906 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v8906; }
    { const char * tb_v8907 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8907; }
    { const char * tb_v8908 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8908; }
    { const char * tb_v8909 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8909; }
    { const char * tb_v8910 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8910; }
    { const char * tb_v8911 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8911; }
    { const char * tb_v8912 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8912; }
    { const char * tb_v8913 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v8913; }
    { const char * tb_v8914 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v8914; }
    { const char * tb_v8915 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8915; }
    { const char * tb_v8916 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8916; }
    { const char * tb_v8917 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8917; }
    { const char * tb_v8918 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8918; }
    { const char * tb_v8919 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8919; }
    { const char * tb_v8920 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v8920; }
    { const char * tb_v8921 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8921; }
    { const char * tb_v8922 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8922; }
    { const char * tb_v8923 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8923; }
    { const char * tb_v8924 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8924; }
    { const char * tb_v8925 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v8925; }
    { const char * tb_v8926 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8926; }
    { const char * tb_v8927 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8927; }
    { const char * tb_v8928 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8928; }
    { const char * tb_v8929 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8929; }
    { const char * tb_v8930 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v8930; }
    { const char * tb_v8931 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v8931; }
    { const char * tb_v8932 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8932; }
    { const char * tb_v8933 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8933; }
    { const char * tb_v8934 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v8934; }
    { const char * tb_v8935 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8935; }
    { const char * tb_v8936 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8936; }
    { const char * tb_v8937 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8937; }
    { const char * tb_v8938 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8938; }
    { const char * tb_v8939 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8939; }
