    { const char * tb_v8986 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8986; }
    { const char * tb_v8987 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v8987; }
    { const char * tb_v8988 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8988; }
    { const char * tb_v8989 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v8989; }
    { const char * tb_v8990 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v8990; }
    { const char * tb_v8991 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v8991; }
    { const char * tb_v8992 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v8992; }
    { const char * tb_v8993 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v8993; }
    { const char * tb_v8994 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8994; }
    { const char * tb_v8995 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v8995; }
    { const char * tb_v8996 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8996; }
    { const char * tb_v8997 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8997; }
    { const char * tb_v8998 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8998; }
    { const char * tb_v8999 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8999; }
    { const char * tb_v9000 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9000; }
    { const char * tb_v9001 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9001; }
    { const char * tb_v9002 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9002; }
    { const char * tb_v9003 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9003; }
    { const char * tb_v9004 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9004; }
    { const char * tb_v9005 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9005; }
    { const char * tb_v9006 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9006; }
    { const char * tb_v9007 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9007; }
    { const char * tb_v9008 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9008; }
    { const char * tb_v9009 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9009; }
