    { const char * tb_v9140 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9140; }
    { const char * tb_v9141 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9141; }
    { const char * tb_v9142 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9142; }
