    { const char * tb_v9144 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9144; }
    { const char * tb_v9145 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9145; }
