    { const char * tb_v9147 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v9147; }
    { const char * tb_v9148 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9148; }
    { const char * tb_v9149 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v9149; }
    { const char * tb_v9150 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v9150; }
    { const char * tb_v9151 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9151; }
    { const char * tb_v9152 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v9152; }
    { const char * tb_v9153 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v9153; }
    { const char * tb_v9154 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v9154; }
    { const char * tb_v9155 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9155; }
    { const char * tb_v9156 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9156; }
