    { const char * tb_v9347 = "        // часть треугольника за камерой: обрезаем всё ближе zn — выходит 0, 3 или 4 угла\n"; *(const char * *)tb_grow(v_lines) = tb_v9347; }
    { const char * tb_v9348 = "        tb_3v *vs[3] = { v0, v1, v2 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9348; }
