    { const char * tb_v9353 = "            if (p->front) { qx[n] = p->cx; qy[n] = p->cy; qz[n] = p->cz; n++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9353; }
    { const char * tb_v9354 = "            if (p->front != q->front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9354; }
    { const char * tb_v9355 = "                double k = (zn - p->cz) / (q->cz - p->cz);\n"; *(const char * *)tb_grow(v_lines) = tb_v9355; }
    { const char * tb_v9356 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9356; }
    { const char * tb_v9357 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9357; }
    { const char * tb_v9358 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9358; }
    { const char * tb_v9359 = "        if (n < 3) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9359; }
    { const char * tb_v9360 = "        double sx[4], sy[4], dd[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v9360; }
    { const char * tb_v9361 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9361; }
    { const char * tb_v9362 = "            double iz = 1 / qz[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9362; }
    { const char * tb_v9363 = "            sx[i] = hw + f * qx[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v9363; }
    { const char * tb_v9364 = "            sy[i] = hh - f * qy[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v9364; }
