    { const char * tb_v9371 = "// ---- 3D в целых числах: так же считает видеокарта (compiler/gpu/tb3.vert, tb.metal) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v9371; }
    { const char * tb_v9372 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v9372; }
    { const char * tb_v9373 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9373; }
    { const char * tb_v9374 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v9374; }
    { const char * tb_v9375 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9375; }
    { const char * tb_v9376 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9376; }
    { const char * tb_v9377 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v9377; }
    { const char * tb_v9378 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9378; }
    { const char * tb_v9379 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v9379; }
    { const char * tb_v9380 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9380; }
    { const char * tb_v9381 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9381; }
    { const char * tb_v9382 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9382; }
    { const char * tb_v9383 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9383; }
    { const char * tb_v9384 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9384; }
    { const char * tb_v9385 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9385; }
    { const char * tb_v9386 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9386; }
    { const char * tb_v9387 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9387; }
    { const char * tb_v9388 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v9388; }
    { const char * tb_v9389 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v9389; }
    { const char * tb_v9390 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9390; }
    { const char * tb_v9391 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9391; }
    { const char * tb_v9392 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9392; }
    { const char * tb_v9393 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9393; }
    { const char * tb_v9394 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9394; }
    { const char * tb_v9395 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9395; }
    { const char * tb_v9396 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9396; }
    { const char * tb_v9397 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v9397; }
    { const char * tb_v9398 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9398; }
    { const char * tb_v9399 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9399; }
    { const char * tb_v9400 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9400; }
    { const char * tb_v9401 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v9401; }
    { const char * tb_v9402 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v9402; }
    { const char * tb_v9403 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v9403; }
    { const char * tb_v9404 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9404; }
    { const char * tb_v9405 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9405; }
    { const char * tb_v9406 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9406; }
    { const char * tb_v9407 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9407; }
    { const char * tb_v9408 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9408; }
    { const char * tb_v9409 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9409; }
    { const char * tb_v9410 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9410; }
    { const char * tb_v9411 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9411; }
    { const char * tb_v9412 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v9412; }
    { const char * tb_v9413 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9413; }
    { const char * tb_v9414 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9414; }
    { const char * tb_v9415 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9415; }
    { const char * tb_v9416 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9416; }
    { const char * tb_v9417 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9417; }
    { const char * tb_v9418 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9418; }
    { const char * tb_v9419 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9419; }
    { const char * tb_v9420 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9420; }
    { const char * tb_v9421 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9421; }
    { const char * tb_v9422 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9422; }
    { const char * tb_v9423 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v9423; }
    { const char * tb_v9424 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v9424; }
    { const char * tb_v9425 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9425; }
    { const char * tb_v9426 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9426; }
    { const char * tb_v9427 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v9427; }
    { const char * tb_v9428 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9428; }
    { const char * tb_v9429 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9429; }
    { const char * tb_v9430 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9430; }
    { const char * tb_v9431 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v9431; }
    { const char * tb_v9432 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9432; }
    { const char * tb_v9433 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9433; }
    { const char * tb_v9434 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9434; }
    { const char * tb_v9435 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9435; }
    { const char * tb_v9436 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9436; }
    { const char * tb_v9437 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9437; }
    { const char * tb_v9438 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9438; }
    { const char * tb_v9439 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9439; }
    { const char * tb_v9440 = "                int32_t *o = dst + 4 * (m->gt + t);\n"; *(const char * *)tb_grow(v_lines) = tb_v9440; }
    { const char * tb_v9441 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9441; }
    { const char * tb_v9442 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v9442; }
    { const char * tb_v9443 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9443; }
    { const char * tb_v9444 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9444; }
    { const char * tb_v9445 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9445; }
    { const char * tb_v9446 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9446; }
    { const char * tb_v9447 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v9447; }
    { const char * tb_v9448 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9448; }
    { const char * tb_v9449 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9449; }
    { const char * tb_v9450 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9450; }
    { const char * tb_v9451 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9451; }
    { const char * tb_v9452 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v9452; }
