    { const char * tb_v9455 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v9455; }
    { const char * tb_v9456 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9456; }
    { const char * tb_v9457 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v9457; }
    { const char * tb_v9458 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v9458; }
    { const char * tb_v9459 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9459; }
