    { const char * tb_v9674 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v9674; }
    { const char * tb_v9675 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v9675; }
    { const char * tb_v9676 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v9676; }
    { const char * tb_v9677 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v9677; }
    { const char * tb_v9678 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v9678; }
    { const char * tb_v9679 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v9679; }
    { const char * tb_v9680 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v9680; }
    { const char * tb_v9681 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v9681; }
    { const char * tb_v9682 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v9682; }
