    { const char * tb_v9713 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v9713; }
    { const char * tb_v9714 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9714; }
    { const char * tb_v9715 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v9715; }
    { const char * tb_v9716 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v9716; }
    { const char * tb_v9717 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9717; }
    { const char * tb_v9718 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9718; }
    { const char * tb_v9719 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9719; }
