    { const char * tb_v9750 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v9750; }
    { const char * tb_v9751 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v9751; }
