    { const char * tb_v10008 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v10008; }
    { const char * tb_v10009 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10009; }
    { const char * tb_v10010 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10010; }
    { const char * tb_v10011 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10011; }
    { const char * tb_v10012 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v10012; }
    { const char * tb_v10013 = "    unsigned char *b = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10013; }
    { const char * tb_v10014 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10014; }
    { const char * tb_v10015 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v10015; }
    { const char * tb_v10016 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10016; }
    { const char * tb_v10017 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v10017; }
    { const char * tb_v10018 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v10018; }
    { const char * tb_v10019 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10019; }
    { const char * tb_v10020 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10020; }
    { const char * tb_v10021 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10021; }
    { const char * tb_v10022 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10022; }
    { const char * tb_v10023 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10023; }
    { const char * tb_v10024 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v10024; }
    { const char * tb_v10025 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10025; }
    { const char * tb_v10026 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v10026; }
    { const char * tb_v10027 = "        const unsigned char *c = b + p + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v10027; }
    { const char * tb_v10028 = "        if ((long)n > sz - p - 8) n = (uint32_t)(sz - p - 8);   // последний кусок обрезан — берём что есть\n"; *(const char * *)tb_grow(v_lines) = tb_v10028; }
    { const char * tb_v10029 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10029; }
    { const char * tb_v10030 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v10030; }
    { const char * tb_v10031 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v10031; }
    { const char * tb_v10032 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10032; }
    { const char * tb_v10033 = "            data = c; dlen = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10033; }
    { const char * tb_v10034 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10034; }
    { const char * tb_v10035 = "        p += 8 + (long)n + (n & 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10035; }
    { const char * tb_v10036 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10036; }
    { const char * tb_v10037 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v10037; }
    { const char * tb_v10038 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10038; }
    { const char * tb_v10039 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v10039; }
    { const char * tb_v10040 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v10040; }
    { const char * tb_v10041 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10041; }
    { const char * tb_v10042 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10042; }
    { const char * tb_v10043 = "    uint32_t bpf = ch * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v10043; }
