    { const char * tb_v10050 = "            const unsigned char *q = data + i * bpf + (uint32_t)k * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v10050; }
    { const char * tb_v10051 = "            float v;\n"; *(const char * *)tb_grow(v_lines) = tb_v10051; }
    { const char * tb_v10052 = "            if (tag == 3) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10052; }
