    { const char * tb_v10057 = "            else if (bits == 24) v = (float)((int32_t)((uint32_t)q[0] << 8 | (uint32_t)q[1] << 16 | (uint32_t)q[2] << 24) >> 8) / 8388608.0f;\n"; *(const char * *)tb_grow(v_lines) = tb_v10057; }
