    { const char * tb_v10104 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v10104; }
    { const char * tb_v10105 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10105; }
    { const char * tb_v10106 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10106; }
    { const char * tb_v10107 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v10107; }
    { const char * tb_v10108 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v10108; }
