    { const char * tb_v10110 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10110; }
    { const char * tb_v10111 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v10111; }
